  await move(3, 2, 2);
  await move(3, 1, 2);
  assert.deepEqual(await ids(2), [4, 1, 2, 3, newB.id, created.id]);
  await stop();
  await start();
  assert.deepEqual(await ids(2), [4, 1, 2, 3, newB.id, created.id]);
  assert.deepEqual((await tasks(2))[2], updated);
  // Returning to C restores its own earlier positions too.
  await move(2, 1, 3);
  await move(2, 2, 3);
  assert.deepEqual(await ids(3), [2, 1]);
});
